from pathlib import Path
import json, html
R=Path(__file__).parent
icons=json.loads((R/'icons.json').read_text())
def icon(n):return '<svg class="dx-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+icons[n]+'</svg>'
def button(n,label,active=False):return '<button class="dx-action"'+(' aria-pressed="true"' if active else '')+'>'+icon(n)+'<span>'+label+'</span></button>'
css=(R/'tokens.css').read_text()+'''
*{box-sizing:border-box}body{margin:0;background:#07090D}.dxfer-workspace{height:900px;display:grid;grid-template-rows:48px 1fr 32px}button{white-space:nowrap}.top{display:flex;align-items:center;padding:0 16px;gap:18px;background:var(--dx-chrome);border-bottom:1px solid var(--dx-border)}.brand{font-weight:700;font-size:16px;letter-spacing:.5px}.file{color:var(--dx-secondary)}.spacer{flex:1}.pill{border:1px solid var(--dx-border);padding:4px 8px;border-radius:4px;color:var(--dx-secondary);font-size:12px}.layout{display:grid;grid-template-columns:200px 1fr 296px;min-height:0}.shelf,.inspector{background:var(--dx-panel);min-height:0}.shelf{padding:12px;border-right:1px solid var(--dx-border)}.shelf .dx-action{width:100%;text-align:left;justify-content:flex-start}.group-title{font-weight:600;margin:18px 8px 6px;color:var(--dx-text);font-size:12px}.group-title:first-child{margin-top:4px}.shelf .dx-icon{width:20px;height:20px}.chev{margin-left:auto;color:var(--dx-muted)}.minor{font-size:12px;color:var(--dx-muted)}.viewport{position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 42%,var(--dx-viewport-depth) 0%,var(--dx-viewport) 72%)}.grid{position:absolute;inset:0;background-image:linear-gradient(var(--dx-grid) 1px,transparent 1px),linear-gradient(90deg,var(--dx-grid) 1px,transparent 1px);background-size:28px 28px}.drawing [stroke="#66D9FF"]{stroke:var(--dx-accent)}.drawing [fill="#66D9FF"]{fill:var(--dx-accent)}.drawing [stroke="#97A5B6"]{stroke:var(--dx-muted)}.drawing text{fill:var(--dx-secondary)}.drawing text[fill="#66D9FF"]{fill:var(--dx-accent)}.view-head{position:absolute;top:16px;left:20px;line-height:1.7}.view-actions{position:absolute;top:14px;right:16px;display:flex;gap:3px;padding:3px;border:1px solid var(--dx-border);background:var(--dx-chrome);border-radius:8px}.drawing{color:var(--dx-viewport-foreground);position:absolute;width:100%;height:100%;inset:0}.instruction{position:absolute;bottom:18px;left:20px;right:20px;display:flex;align-items:center;gap:10px;padding:10px 12px;background:#10141BF2;border:1px solid var(--dx-border-strong);border-radius:8px}.key{font-size:11px;border:1px solid var(--dx-border-strong);border-radius:3px;padding:1px 5px;color:var(--dx-secondary)}.inspector{border-left:1px solid var(--dx-border);display:flex;flex-direction:column}.section{padding:16px;border-bottom:1px solid var(--dx-border)}.section h2{font-size:14px;margin:0 0 4px}.section h3{font-size:12px;margin:0 0 10px;font-weight:600}.slots{display:grid;gap:8px;margin-top:16px}.slot{display:flex;align-items:center;gap:9px;background:var(--dx-input);border:1px solid var(--dx-border-strong);border-radius:6px;padding:8px 10px}.slot .dx-icon{color:var(--dx-success)}.value{margin-top:2px}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:16px}.field{margin-top:5px;display:flex;justify-content:space-between}.row{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:12px}.valid{display:flex;align-items:center;gap:7px;color:var(--dx-success);font-size:12px}.tool-footer{padding:16px;background:var(--dx-chrome);border-top:1px solid var(--dx-border)}.tool-footer .buttons{display:flex;gap:8px;justify-content:flex-end;margin-top:14px}.stats{display:grid;grid-template-columns:1fr auto;gap:9px;font-size:12px}.constraint-row{display:flex;gap:8px;align-items:center;margin:10px 0;color:var(--dx-secondary)}.constraint-row .dx-icon{width:16px;height:16px}.status{display:flex;align-items:center;gap:18px;padding:0 16px;border-top:1px solid var(--dx-border);background:var(--dx-chrome);font-size:12px;color:var(--dx-secondary)}.green{color:var(--dx-success)}.review-note{position:absolute;top:75px;right:16px;color:var(--dx-muted);font-size:11px}.state-board{height:auto;padding:36px;display:block}.state-grid{display:flex;gap:16px;flex-wrap:wrap}.state-grid>div{width:200px;background:var(--dx-panel);padding:16px;border:1px solid var(--dx-border);border-radius:8px}.state-grid p{color:var(--dx-muted);font-size:12px}.explicit-focus{outline:2px solid var(--dx-accent);outline-offset:2px}.invalid{color:var(--dx-danger);padding:12px;border:1px solid var(--dx-danger);border-radius:6px;background:var(--dx-danger-soft)}
'''
shelf='<div class="group-title">Create geometry</div>'+''.join(button(n,l) for n,l in [('line','Line'),('rectangle','Rectangle'),('circle','Circle'),('arc','Arc'),('spline','Spline'),('ellipse','Ellipse'),('slot','Slot')])+'<div class="minor" style="padding:8px">More create tools ▾</div><div class="group-title">Modify geometry</div>'+''.join(button(n,l,n=='fillet') for n,l in [('trim','Trim'),('extend','Extend'),('fillet','Fillet'),('chamfer','Chamfer'),('offset','Offset'),('dimension','Dimension')])+'<div class="group-title">Transform & pattern</div>'+button('move','Move / rotate / scale')+button('linear-pattern','Pattern')+'<div class="group-title">Relations & preparation</div>'+button('constraints','Constraints')+button('layers','Cleanup & grain')
svg='''<svg class="drawing" viewBox="0 0 944 820" xmlns="http://www.w3.org/2000/svg"><defs><pattern id="hatch" width="12" height="12" patternUnits="userSpaceOnUse" patternTransform="rotate(32)"><path d="M0 0v12" stroke="#66D9FF" stroke-opacity=".24"/></pattern></defs><g fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M180 590V300a70 70 0 0 1 70-70h370V590Z" stroke="currentColor" stroke-width="2"/><path d="M180 300V230h70" stroke="#66D9FF" stroke-width="1.5" stroke-dasharray="5 5"/><path d="M180 300a70 70 0 0 1 70-70" stroke="#66D9FF" stroke-width="3"/><path d="M180 300V230h70a70 70 0 0 0-70 70Z" fill="url(#hatch)" stroke="none"/><circle cx="292" cy="360" r="40" stroke="currentColor" stroke-width="2"/><circle cx="506" cy="360" r="40" stroke="currentColor" stroke-width="2"/><path d="M292 476h214a30 30 0 0 1 0 60H292a30 30 0 0 1 0-60Z" stroke="currentColor" stroke-width="2"/><path d="M250 300 212 261 134 261" stroke="#66D9FF"/><circle cx="250" cy="300" r="3" fill="#66D9FF" stroke="none"/><path d="M180 633h440m-434-4-6 4 6 4m428-8 6 4-6 4M180 600v44m440-44v44" stroke="#97A5B6"/><path d="M50 750h42m-42 0v-42" stroke="#97A5B6"/><path d="M50 750h42" stroke="#FF6C7C"/><path d="M50 750v-42" stroke="#79E1AB"/></g><g font-family="sans-serif" font-size="13" fill="#BBC5D1"><text x="120" y="248" fill="#66D9FF">R 0.750 in</text><text x="361" y="625">4.714 in</text><text x="99" y="755">X</text><text x="46" y="699">Y</text></g></svg>'''
inspector='<div class="section"><div class="minor">Active tool</div><h2>Fillet</h2><div class="minor">Round the corner between two edges.</div><div class="slots">'+''.join('<div class="slot">'+icon('check')+'<div><div class="minor">'+name+'</div><div class="value">'+val+'</div></div></div>' for name,val in [('First edge','Line 04'),('Second edge','Line 05')])+'</div><div class="twocol"><label class="minor">Radius<div class="dx-field field"><span style="color:var(--dx-text)">0.750</span><span>in</span></div></label><label class="minor">Corner mode<div class="dx-field field"><span style="color:var(--dx-text)">Trim</span><span>⌄</span></div></label></div><div class="row"><span>Keep original edges</span><span class="pill">Off</span></div></div><div class="section"><h3>Selection</h3><div class="stats"><span class="minor">Entities</span><span>2 lines</span><span class="minor">Document units</span><span>Inches</span><span class="minor">Layer</span><span>Cut profile</span></div></div><div class="section"><h3>Relations</h3><div class="constraint-row">'+icon('horizontal')+'Horizontal <span class="spacer"></span><span class="minor">Line 04</span></div><div class="constraint-row">'+icon('vertical')+'Vertical <span class="spacer"></span><span class="minor">Line 05</span></div><div class="minor">Only show relations for this selection.</div></div><div class="spacer"></div><div class="tool-footer"><div class="valid">'+icon('check')+'Preview valid · 1 corner affected</div><div class="buttons">'+button('close','Cancel')+'<button class="dx-action dx-primary">'+icon('check')+'Apply fillet</button></div></div>'
page='<!doctype html><html lang="en"><meta charset="utf-8"><title>DXFer workspace design target</title><style>'+css+'</style><body><main class="dxfer-workspace"><header class="top"><span class="brand">DXFer</span><span class="file">Bracket profile.dxf <span style="color:var(--dx-accent)">•</span></span><span class="pill">Inches</span><span class="spacer"></span>'+button('open','File')+button('search','Find a command')+button('undo','Undo')+button('redo','Redo')+button('download','Export DXF')+'</header><div class="layout"><nav class="shelf">'+shelf+'</nav><section class="viewport"><div class="grid"></div><div class="view-head"><strong>Top · orthographic</strong><div class="minor">Sketch editing</div></div><div class="view-actions">'+button('fit','Fit')+button('grid','Grid',True)+button('constraints','Relations',True)+'</div><div class="review-note">DESIGN TARGET · illustrative geometry</div>'+svg+'<div class="instruction">'+icon('fillet')+'<span>Fillet preview ready. Edit radius or apply.</span><span class="spacer"></span><span class="key">Enter</span><span>Apply</span><span class="key">Esc</span><span>Cancel</span></div></section><aside class="inspector">'+inspector+'</aside></div><footer class="status"><span class="green">●</span><span>Preview · changes not committed</span><span class="spacer"></span><span>2 selected</span><span>Cut length 18.42 in</span><span>Contours: 1 closed</span><span>Snap: endpoint</span></footer></main></body></html>'
(R/'workspace-target.html').write_text(page)
states=[('Default','dx-action',''),('Hover','dx-action','background:var(--dx-hover)'),('Selected','dx-action','background:var(--dx-selected);color:var(--dx-accent);box-shadow:inset 2px 0 var(--dx-accent)'),('Keyboard focus','dx-action explicit-focus',''),('Primary commit','dx-action dx-primary',''),('Destructive','dx-action dx-danger',''),('Disabled','dx-action','color:var(--dx-disabled)')]
board='<!doctype html><html lang="en"><meta charset="utf-8"><title>DXFer component states</title><style>'+css+'</style><body><main class="dxfer-workspace state-board"><h1>Component states</h1><p class="minor">Design specification · no application behavior simulated</p><div class="state-grid">'+''.join('<div><h3>'+l+'</h3><button class="'+cl+'"'+(' aria-pressed="true"' if l=='Selected' else ' disabled' if l=='Disabled' else '')+' style="'+st+'">'+icon('fillet')+'Fillet</button><p>34 px compact target · 20 px glyph</p></div>' for l,cl,st in states)+'</div><h2>Recoverable relation conflict</h2><div class="invalid" style="max-width:580px">'+icon('conflict')+'<strong>Vertical conflicts with Horizontal on Line 04.</strong><p>The operation was not applied. Remove Horizontal or choose another line.</p><button class="dx-action">Show conflicting relation</button></div><h2>Numeric parameter</h2><label>Radius (in)<br><input class="dx-field" value="0.750" aria-label="Radius in inches"></label><h2>Viewport state</h2><p>Normal = neutral solid edge. Selected = cyan edge + square handles. Preview = cyan dashed result + “Preview” label. Protected = amber edge + lock marker. Invalid = red broken boundary + error marker + reason.</p></main></body></html>'
(R/'component-states.html').write_text(board)
